def base32_decode(s):
    alpha = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567'
    s = s.upper().rstrip('=')
    bits = 0
    nbits = 0
    out = bytearray()
    for c in s:
        bits = (bits << 5) | alpha.index(c)
        nbits += 5
        if nbits >= 8:
            nbits -= 8
            out.append((bits >> nbits) & 0xFF)
    return bytes(out)

def uniq_stable(items):
    out = []
    for x in items:
        if not any(x == y for y in out):
            out.append(x)
    return out

def time_ago(seconds):
    if seconds < 60:
        return f'{seconds}s'
    if seconds < 3600:
        return f'{seconds // 60}m'
    if seconds < 86400:
        return f'{seconds // 3600}h'
    return f'{seconds // 86400}d'

def balanced_parens_depth(s):
    depth = best = 0
    for c in s:
        if c == '(':
            depth += 1
            best = max(best, depth)
        elif c == ')':
            depth -= 1
            if depth < 0:
                return -1
    return best if depth == 0 else -1

def hex_to_rgb(h):
    h = h.lstrip('#')
    if len(h) == 3:
        h = ''.join(c * 2 for c in h)
    if len(h) != 6:
        raise ValueError('bad length')
    try:
        return (int(h[0:2], 16), int(h[2:4], 16), int(h[4:6], 16))
    except ValueError:
        raise ValueError('bad hex')

